use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn transient_failure_then_success_uses_configured_policy() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 5,
        max_delay_ms: 8,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls == 1 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![5]);
}

